    return pd.read_csv(path)

def process(metroFraudReports2024, floridaMsaFraudOther) -> pd.DataFrame:
    import pandas as pd

    def find_msa_col(df):
        for c in df.columns:
            cl = str(c).strip().lower()
            if 'metropolitan' in cl or 'msa' in cl or cl in {'metro area', 'metropolitan area'}:
                return c
        return None

    def find_count_cols(df):
        cols = []
        for c in df.columns:
            cl = str(c).strip().lower()
            if 'report' in cl and ('count' in cl or 'number' in cl or cl.endswith('reports')):
                cols.append(c)
            elif cl in {'reports', 'report count', 'total reports', 'total_report_count'}:
                cols.append(c)
        # fallback: any numeric col with 'report' in name
        if not cols:
            for c in df.columns:
                cl = str(c).strip().lower()
                if 'report' in cl:
                    cols.append(c)
        return cols

    target = 'miami-fort lauderdale-west palm beach'

    # --- metro dataset ---
    m = metroFraudReports2024.copy()
    msa_col_m = find_msa_col(m)
    if msa_col_m is None:
        msa_col_m = m.columns[0]
    m['_msa'] = m[msa_col_m].astype(str).str.strip().str.lower()
    msub = m[m['_msa'].str.contains('miami') & m['_msa'].str.contains('fort') & m['_msa'].str.contains('palm')]

    # choose count column
    m_count_cols = find_count_cols(m)
    m_count = None
    for c in m_count_cols:
        if c in msub.columns:
            s = pd.to_numeric(msub[c], errors='coerce').dropna()
            if len(s) > 0:
                m_count = float(s.iloc[0])
                break

    # --- florida msa dataset ---
    f = floridaMsaFraudOther.copy()
    msa_col_f = find_msa_col(f)
    if msa_col_f is None:
        msa_col_f = f.columns[0]
    f['_msa'] = f[msa_col_f].astype(str).str.strip().str.lower()
    fsub = f[f['_msa'].str.contains('miami') & f['_msa'].str.contains('fort') & f['_msa'].str.contains('palm')]

    f_count_cols = find_count_cols(f)
    f_count = None
    for c in f_count_cols:
        if c in fsub.columns:
            s = pd.to_numeric(fsub[c], errors='coerce').dropna()
            if len(s) > 0:
                f_count = float(s.iloc[0])
                break

    consistent = (m_count is not None) and (f_count is not None) and (m_count == f_count)

    return pd.DataFrame([{
        'consistent': bool(consistent),
        'metro_count': m_count,
        'florida_count': f_count,
        'metro_msa_matches': int(len(msub)),
        'florida_msa_matches': int(len(fsub)),
        'metro_msa_col': str(msa_col_m),
        'florida_msa_col': str(msa_col_f)
    }])

def load() -> pd.DataFrame:
    import pandas as pd
    path = "data/legal/input/csn-data-book-2024-csv/CSVs/2024_CSN_Metropolitan_Areas_Fraud_and_Other_Reports.csv"
    # Try common encodings seen in FTC/CSN exports.
    try:
        return pd.read_csv(path, encoding="utf-8")
    except UnicodeDecodeError:
        try:
            return pd.read_csv(path, encoding="cp1252")
        except UnicodeDecodeError:
            return pd.read_csv(path, encoding="latin-1")
